actions.action:
pu_proces: f.pu_proces, pu_ucet: f.pu_ucet, pu_stav: f.pu_stav,
pu_stav_label: f.pu_stav_label, pu_email: f.pu_email, pu_pridelene: f.pu_pridelene;

// Zoznamy sa citaju z instancie, nie z tohto XML. Keby boli natvrdo, kazda
// nova appka a kazdy novy ucet by znamenali zasah do tejto siete.
change pu_proces options { processOptions() }
change pu_ucet options { userOptions() }

change pu_stav value { "koncept" }
change pu_stav_label value { "Rozpísaný" }
change pu_pridelene value { "(zatiaľ nič)" }
changeCaseProperty("title").about { nazov(pu_email, "Rozpísaný") }
changeCaseProperty("color").about { "grey" }

document.function:
{ def u ->
    // `?.` chráni pred null, nie pred chýbajúcou property.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def pu_email, def stav ->
    def mail = ((pu_email.value ?: "") as String).trim()
    return (stav as String) + " · " + (mail ?: "Nový používateľ")
}

{ def pole ->
    // Hodnota multichoice_map je zoznam klucov, ale cez REST aj z UI prichadza
    // v roznych obalkach. Bez tohto by sa `each` prehnal po znakoch retazca.
    def raw = pole.value
    if (raw == null) return []
    if (raw instanceof Collection) return raw.collect { it as String }
    if (raw.hasProperty("value") && raw.value instanceof Collection) {
        return raw.value.collect { it as String }
    }
    def s = (raw as String).trim()
    return s ? [s] : []
}

{ def hodnota ->
    def mail = ((hodnota ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

{ def pu_zoznam ->
    // Akumulator je text, jeden riadok = "importId|siet|verzia". Tabulator by
    // sa cez REST aj cez formular stratil, zvisla ciara nie.
    def out = []
    ((pu_zoznam.value ?: "") as String).split("\n").each { String riadok ->
        def r = riadok.trim()
        if (!r) return
        def casti = r.split("\\|", -1)
        if (casti.length < 2) return
        out << [rola: casti[0], siet: casti[1], verzia: (casti.length > 2 ? casti[2] : "vsetky")]
    }
    return out
}

{ def polozky ->
    if (!polozky) return "(zatiaľ nič)"
    return polozky.collect { p ->
        def v = (p.verzia == null || p.verzia == "" || p.verzia == "vsetky")
                ? "všetky verzie" : ("verzia " + (p.verzia as String).replace("_", "."))
        return "• " + p.rola + " — " + p.siet + " (" + v + ")"
    }.join("\n")
}

actions.action:
t_pu_zadanie: t.t_pu_zadanie, pu_rezim: f.pu_rezim, pu_ucet: f.pu_ucet,
pu_email: f.pu_email, pu_heslo: f.pu_heslo;

// Pole na vyber existujuceho uctu ma zmysel len v rezime "existujuci",
// a e-mail sa pri uprave menit neda - je to prihlasovacie meno aj kluc,
// podla ktoreho ucty hlada seed.json aj kazdy test.
if ((pu_rezim.value as String) == "existujuci") {
    make pu_ucet, editable on t_pu_zadanie when { true }
    make pu_ucet, required on t_pu_zadanie when { true }
    make pu_email, visible on t_pu_zadanie when { true }
    make pu_heslo, editable on t_pu_zadanie when { true }
} else {
    make pu_ucet, hidden on t_pu_zadanie when { true }
    make pu_email, editable on t_pu_zadanie when { true }
    make pu_email, required on t_pu_zadanie when { true }
    make pu_heslo, required on t_pu_zadanie when { true }
}

pu_ucet: f.pu_ucet, pu_userid: f.pu_userid, pu_meno: f.pu_meno,
pu_priezvisko: f.pu_priezvisko, pu_email: f.pu_email, pu_authority: f.pu_authority,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

// Predvyplnenie formulara zo skutocneho stavu uctu. Bez tohto by uprava
// znamenala vypisat vsetko znova a co by admin nevyplnil, to by sa stratilo.
def id = (pu_ucet.value ?: "") as String
def snap = userSnapshot(id)
change pu_userid value { id }
change pu_meno value { snap.meno }
change pu_priezvisko value { snap.priezvisko }
change pu_email value { snap.email }
change pu_authority value { (snap.authorities ?: []) as List }

// Sucasne role sa nacitaju do zoznamu, aby bolo vidno, s cim sa zacina.
// Verzia je "vsetky": snapshot verzie nerozlisuje a plosne pridelenie je
// aj tak to, co chce clovek skoro vzdy.
def riadky = []
((snap.roly ?: [:]) as Map).each { siet, zoznamRoli ->
    (zoznamRoli ?: []).each { rola -> riadky << (rola + "|" + siet + "|vsetky") }
}
change pu_zoznam value { riadky.join("\n") }
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }

pu_proces: f.pu_proces, pu_roly: f.pu_roly, pu_verzia: f.pu_verzia;

// Druhy krok vyberu: z vybraneho procesu sa doplnia JEHO role a JEHO verzie.
def siet = (pu_proces.value ?: "") as String
change pu_roly options { processRoleOptions(siet) }
change pu_roly value { [] }
change pu_verzia options { processVersionOptions(siet) }
change pu_verzia value { "vsetky" }

pu_proces: f.pu_proces, pu_roly: f.pu_roly, pu_verzia: f.pu_verzia,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

// Bez tohto tlacidla by vyber druheho procesu prepisal ten prvy: `pu_roly`
// drzi role len prave vybraneho procesu.
def siet = (pu_proces.value ?: "") as String
def verzia = ((pu_verzia.value ?: "vsetky") as String)
def vybrane = ako_zoznam(pu_roly)
if (siet && vybrane) {
    def uz = rozbor_zoznamu(pu_zoznam)
    def riadky = uz.collect { it.rola + "|" + it.siet + "|" + it.verzia }
    vybrane.each { String rola ->
        def r = rola + "|" + siet + "|" + verzia
        if (!riadky.contains(r)) { riadky << r }
    }
    change pu_zoznam value { riadky.join("\n") }
    change pu_roly value { [] }
}
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }

pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

change pu_zoznam value { "" }
change pu_pridelene value { "(zatiaľ nič)" }

pu_rezim: f.pu_rezim, pu_email: f.pu_email, pu_heslo: f.pu_heslo,
pu_ucet: f.pu_ucet, pu_authority: f.pu_authority;

// Co `required` neoveri a co po vykonani uz nema kto vratit.
def rezim = (pu_rezim.value ?: "novy") as String
def mail = ((pu_email.value ?: "") as String).trim()
def heslo = (pu_heslo.value ?: "") as String

if (rezim == "novy") {
    if (!je_email(mail)) {
        throw new java.lang.IllegalStateException("E-mail nemá platný tvar: " + mail)
    }
    if (findUserByEmail(mail) != null) {
        throw new java.lang.IllegalStateException("Používateľ s e-mailom " + mail + " už existuje.")
    }
    if (!registrationService.isPasswordSufficient(heslo)) {
        throw new java.lang.IllegalStateException("Heslo nespĺňa požiadavky instancie.")
    }
} else {
    if (!((pu_ucet.value ?: "") as String).trim()) {
        throw new java.lang.IllegalStateException("Vyberte účet, ktorý sa má upraviť.")
    }
    // Pri uprave je heslo volitelne - meni sa len ked je vyplnene.
    if (heslo && !registrationService.isPasswordSufficient(heslo)) {
        throw new java.lang.IllegalStateException("Nové heslo nespĺňa požiadavky instancie.")
    }
}
if (!ako_zoznam(pu_authority).contains("ROLE_USER")) {
    throw new java.lang.IllegalStateException(
            "Bez ROLE_USER sa používateľ prihlási a neuvidí žiadne zobrazenie.")
}

pu_rezim: f.pu_rezim, pu_meno: f.pu_meno, pu_priezvisko: f.pu_priezvisko,
pu_email: f.pu_email, pu_heslo: f.pu_heslo, pu_authority: f.pu_authority,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene, pu_userid: f.pu_userid,
pu_ucet: f.pu_ucet, pu_stav: f.pu_stav, pu_stav_label: f.pu_stav_label,
pu_vysledok: f.pu_vysledok, pu_zmenil: f.pu_zmenil, pu_zmenene_o: f.pu_zmenene_o;

def rezim = (pu_rezim.value ?: "novy") as String
def mail = ((pu_email.value ?: "") as String).trim()
def meno = ((pu_meno.value ?: "") as String).trim()
def priezvisko = ((pu_priezvisko.value ?: "") as String).trim()
def heslo = (pu_heslo.value ?: "") as String
def authorities = ako_zoznam(pu_authority)
def riadky = []
// Ucet sa NEDRZI ako objekt - kazda zmena uklada cely dokument, takze dve
// zmeny cez ten isty objekt by sa navzajom prepisali. Drzime len id.
def cieloveId = null

if (rezim == "novy") {
    def novy = createNewUser(meno, priezvisko, mail, heslo, authorities)
    cieloveId = novy.stringId as String
    change pu_userid value { cieloveId }
    riadky << ("účet vytvorený: " + mail)
} else {
    def id = ((pu_userid.value ?: pu_ucet.value ?: "") as String)
    cieloveId = id
    if (findUserById(id) == null) {
        throw new java.lang.IllegalStateException("Účet sa nenašiel: " + id)
    }
    def predtym = userSnapshot(id)
    updateUserProfile(id, meno, priezvisko)
    setUserAuthorities(id, authorities)
    if (heslo) {
        changeUserPassword(id, heslo)
        riadky << "heslo zmenené"
    }
    // Role, ktore ucet mal a v zozname uz nie su, sa ODOBERU. Uprava je
    // nastavenie stavu, nie pridavanie - inak by sa rola nedala nikdy zrusit.
    def chceme = rozbor_zoznamu(pu_zoznam).collect { it.rola + "|" + it.siet } as Set
    ((predtym.roly ?: [:]) as Map).each { siet, zoznamRoli ->
        (zoznamRoli ?: []).each { rola ->
            if (!chceme.contains((rola as String) + "|" + (siet as String))) {
                setProcessRole(id, rola as String, siet as String, "", false)
                riadky << ("odobraná rola: " + rola + " (" + siet + ")")
            }
        }
    }
    riadky << ("účet upravený: " + mail)
    change pu_userid value { id }
}

riadky << ("systémové oprávnenia: " + (authorities ? authorities.join(", ") : "žiadne"))

def pridelene = []
def zlyhane = []
rozbor_zoznamu(pu_zoznam).each { p ->
    if (setProcessRole(cieloveId, p.rola as String, p.siet as String, p.verzia as String, true)) {
        pridelene << (p.rola + " (" + p.siet + ")")
    } else {
        zlyhane << (p.rola + " (" + p.siet + ")")
    }
}
riadky << (pridelene ? "procesné role: " + pridelene.join(", ") : "procesné role: žiadne")
if (zlyhane) {
    riadky << ("NEPODARILO SA prideliť: " + zlyhane.join(", "))
}

change pu_stav value { zlyhane ? "ciastocne" : "hotovo" }
change pu_stav_label value { zlyhane ? "Hotový s výhradou" : "Hotový" }
change pu_vysledok value { riadky.join("\n") }
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }
change pu_zmenil value { kto(loggedUser()) }
change pu_zmenene_o value { java.time.LocalDateTime.now() }

// Heslo z pripadu prec. Zostalo by v datach citatelne pre kazdeho, kto ma
// na case `view` - a to je pri sprave uzivatelov to posledne, co chceme.
change pu_heslo value { "" }

changeCaseProperty("title").about {
    nazov(pu_email, zlyhane ? "Hotový s výhradou" : "Hotový")
}
changeCaseProperty("color").about { zlyhane ? "orange" : "green" }

pu_proces: f.pu_proces, pu_roly: f.pu_roly, pu_verzia: f.pu_verzia;

def siet = (pu_proces.value ?: "") as String
change pu_roly options { processRoleOptions(siet) }
change pu_roly value { [] }
change pu_verzia options { processVersionOptions(siet) }
change pu_verzia value { "vsetky" }

pu_proces: f.pu_proces, pu_roly: f.pu_roly, pu_verzia: f.pu_verzia,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

def siet = (pu_proces.value ?: "") as String
def verzia = ((pu_verzia.value ?: "vsetky") as String)
def vybrane = ako_zoznam(pu_roly)
if (siet && vybrane) {
    def uz = rozbor_zoznamu(pu_zoznam)
    def riadky = uz.collect { it.rola + "|" + it.siet + "|" + it.verzia }
    vybrane.each { String rola ->
        def r = rola + "|" + siet + "|" + verzia
        if (!riadky.contains(r)) { riadky << r }
    }
    change pu_zoznam value { riadky.join("\n") }
    change pu_roly value { [] }
}
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }

pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

change pu_zoznam value { "" }
change pu_pridelene value { "(zatiaľ nič)" }

pu_proces: f.pu_proces, pu_userid: f.pu_userid, pu_zoznam: f.pu_zoznam,
pu_pridelene: f.pu_pridelene, pu_authority: f.pu_authority;

// Pri kazdom otvoreni sa ponuka procesov aj stav uctu nacita ZNOVA. Bez toho
// by uprava pracovala s tym, co bolo v case zalozenia pripadu - a keby medzitym
// niekto pridal siet alebo zmenil rolu inde, admin by to prepisal starym stavom.
change pu_proces options { processOptions() }

def id = ((pu_userid.value ?: "") as String).trim()
if (id) {
    def snap = userSnapshot(id)
    change pu_authority value { (snap.authorities ?: []) as List }
    def riadky = []
    ((snap.roly ?: [:]) as Map).each { siet, zoznamRoli ->
        (zoznamRoli ?: []).each { rola -> riadky << (rola + "|" + siet + "|vsetky") }
    }
    change pu_zoznam value { riadky.join("\n") }
    change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }
}

pu_userid: f.pu_userid, pu_heslo: f.pu_heslo, pu_authority: f.pu_authority;

if (!((pu_userid.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException("Prípad nemá naviazaný účet.")
}
def heslo = (pu_heslo.value ?: "") as String
if (heslo && !registrationService.isPasswordSufficient(heslo)) {
    throw new java.lang.IllegalStateException("Nové heslo nespĺňa požiadavky instancie.")
}
if (!ako_zoznam(pu_authority).contains("ROLE_USER")) {
    throw new java.lang.IllegalStateException(
            "Bez ROLE_USER sa používateľ prihlási a neuvidí žiadne zobrazenie.")
}

pu_userid: f.pu_userid, pu_meno: f.pu_meno, pu_priezvisko: f.pu_priezvisko,
pu_email: f.pu_email, pu_heslo: f.pu_heslo, pu_authority: f.pu_authority,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene, pu_stav: f.pu_stav,
pu_stav_label: f.pu_stav_label, pu_vysledok: f.pu_vysledok,
pu_zmenil: f.pu_zmenil, pu_zmenene_o: f.pu_zmenene_o;

def id = ((pu_userid.value ?: "") as String).trim()
def cieloveId = id
if (findUserById(id) == null) {
    throw new java.lang.IllegalStateException("Účet sa nenašiel: " + id)
}
def predtym = userSnapshot(id)
def authorities = ako_zoznam(pu_authority)
def heslo = (pu_heslo.value ?: "") as String
def riadky = []

updateUserProfile(id, ((pu_meno.value ?: "") as String).trim(),
                      ((pu_priezvisko.value ?: "") as String).trim())
setUserAuthorities(id, authorities)
if (heslo) {
    changeUserPassword(id, heslo)
    riadky << "heslo zmenené"
}
riadky << ("systémové oprávnenia: " + (authorities ? authorities.join(", ") : "žiadne"))

def chceme = rozbor_zoznamu(pu_zoznam).collect { it.rola + "|" + it.siet } as Set
((predtym.roly ?: [:]) as Map).each { siet, zoznamRoli ->
    (zoznamRoli ?: []).each { rola ->
        if (!chceme.contains((rola as String) + "|" + (siet as String))) {
            setProcessRole(id, rola as String, siet as String, "", false)
            riadky << ("odobraná rola: " + rola + " (" + siet + ")")
        }
    }
}

def pridelene = []
def zlyhane = []
rozbor_zoznamu(pu_zoznam).each { p ->
    if (setProcessRole(cieloveId, p.rola as String, p.siet as String, p.verzia as String, true)) {
        pridelene << (p.rola + " (" + p.siet + ")")
    } else {
        zlyhane << (p.rola + " (" + p.siet + ")")
    }
}
riadky << (pridelene ? "procesné role: " + pridelene.join(", ") : "procesné role: žiadne")
if (zlyhane) {
    riadky << ("NEPODARILO SA prideliť: " + zlyhane.join(", "))
}

change pu_stav value { zlyhane ? "ciastocne" : "hotovo" }
change pu_stav_label value { zlyhane ? "Hotový s výhradou" : "Hotový" }
change pu_vysledok value { riadky.join("\n") }
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }
change pu_zmenil value { kto(loggedUser()) }
change pu_zmenene_o value { java.time.LocalDateTime.now() }
